package wavchunk

import (
	"bufio"
	"errors"
	"fmt"
	"io/fs"
	"math"
	"os"
	"regexp"
	"sort"
	"strconv"
	"time"
)

const (
	filePerm = 0o600

	partialSuffix = ".partial"
	bufferSize    = 64 << 10
	maxChunk      = 24 * time.Hour
)

// Operation names used in error messages.
const (
	opOpenDir  = "open directory"
	opScan     = "scan directory"
	opCreate   = "create chunk"
	opWrite    = "write chunk"
	opFinalize = "finalize chunk"
	opRename   = "rename chunk"
)

// chunkName matches final and temporary chunk names; names are generated by the writer, never taken from input.
var chunkName = regexp.MustCompile(`^chunk-(\d{6})\.wav(\.partial)?$`)

var (
	// ErrClosed means the writer was closed.
	ErrClosed = errors.New("wavchunk: writer closed")

	// ErrPartialFrame means Write got bytes that are not a whole number of frames.
	ErrPartialFrame = errors.New("wavchunk: partial frame")

	// ErrChunkTooLong means a chunk of the requested duration would not fit into a WAV file (4 GiB).
	ErrChunkTooLong = errors.New("wavchunk: chunk too long")
)

// Config configures a Writer.
type Config struct {
	// Dir is an existing directory; every file of the writer is created inside it.
	Dir string

	// ChunkDuration is the length of every chunk except the last; it is turned into a frame count.
	ChunkDuration time.Duration

	// OnChunk, if set, is called after a chunk has been made final.
	OnChunk func(Chunk)
}

// Chunk describes a chunk that has been made final.
type Chunk struct {
	Name   string
	Format Format
	Frames int64
}

// Duration is the audio length counted by frames.
func (c Chunk) Duration() time.Duration { return c.Format.Duration(c.Frames) }

// Writer splits a stream of frames into chunk files. It is not safe for concurrent use.
type Writer struct {
	root *os.Root
	cfg  Config

	format   Format
	perChunk int64 // frames per chunk for format
	next     int   // number of the next chunk

	cur       *os.File
	buf       *bufio.Writer
	curName   string
	curFrames int64

	err    error // sticky: after a failed write the writer refuses more data
	closed bool
}

// New opens the directory. Numbering continues after the highest chunk already present, so a restarted recorder
// never overwrites the chunks of a run that was killed. No file is created before the first Write.
func New(cfg Config, f Format) (*Writer, error) {
	if cfg.ChunkDuration <= 0 || cfg.ChunkDuration > maxChunk {
		return nil, fmt.Errorf("wavchunk: chunk duration %v must be in (0, %v]", cfg.ChunkDuration, maxChunk)
	}

	root, err := os.OpenRoot(cfg.Dir)
	if err != nil {
		return nil, fmt.Errorf("wavchunk: %s: %w", opOpenDir, err)
	}

	last, err := lastNumber(root)
	if err != nil {
		_ = root.Close()
		return nil, err
	}

	w := &Writer{root: root, cfg: cfg, next: last + 1}
	if err := w.setFormat(f); err != nil {
		_ = root.Close()
		return nil, err
	}
	return w, nil
}

// Format returns the current format.
func (w *Writer) Format() Format { return w.format }

// FramesPerChunk returns the rotation threshold for the current format.
func (w *Writer) FramesPerChunk() int64 { return w.perChunk }

// SetFormat switches the format. When it differs from the current one, the current chunk is made final first,
// so every chunk has a single format (a reopened stream may come back with another mix format).
func (w *Writer) SetFormat(f Format) error {
	if err := w.usable(); err != nil {
		return err
	}
	if f == w.format {
		return nil
	}
	if err := f.Validate(); err != nil {
		return err
	}
	if err := w.finish(); err != nil {
		return err
	}
	return w.setFormat(f)
}

// Write appends whole frames in the current format, rotating chunks every FramesPerChunk frames.
func (w *Writer) Write(p []byte) error {
	if err := w.usable(); err != nil {
		return err
	}
	block := w.format.BlockAlign()
	if len(p)%block != 0 {
		return fmt.Errorf("%w: %d bytes, frame is %d bytes", ErrPartialFrame, len(p), block)
	}

	for len(p) > 0 {
		if w.cur == nil {
			if err := w.start(); err != nil {
				return w.fail(err)
			}
		}

		n := min(int64(len(p)/block), w.perChunk-w.curFrames)
		if _, err := w.buf.Write(p[:n*int64(block)]); err != nil {
			return w.fail(fmt.Errorf("wavchunk: %s: %w", opWrite, err))
		}
		w.curFrames += n
		p = p[n*int64(block):]

		if w.curFrames == w.perChunk {
			if err := w.finish(); err != nil {
				return err
			}
		}
	}
	return nil
}

// Close makes the current chunk final (a chunk without frames is never created) and releases the directory.
func (w *Writer) Close() error {
	if w.closed {
		return nil
	}
	w.closed = true

	var err error
	if w.err == nil {
		err = w.finish()
	} else if w.cur != nil {
		// Keep the .partial file of a failed chunk on disk: Validate reports it, nothing is silently dropped.
		_ = w.cur.Close()
	}
	return errors.Join(err, w.root.Close())
}

func (w *Writer) usable() error {
	switch {
	case w.closed:
		return ErrClosed
	case w.err != nil:
		return w.err
	}
	return nil
}

func (w *Writer) fail(err error) error {
	w.err = err
	return err
}

func (w *Writer) setFormat(f Format) error {
	if err := f.Validate(); err != nil {
		return err
	}

	// Split seconds and the remainder so that the product cannot overflow int64 (ChunkDuration <= maxChunk).
	d, rate := w.cfg.ChunkDuration, int64(f.SampleRate)
	frames := int64(d/time.Second)*rate + int64(d%time.Second)*rate/int64(time.Second)
	if frames < 1 {
		frames = 1
	}
	if frames > (math.MaxUint32-int64(headerLen(f)))/int64(f.BlockAlign()) {
		return fmt.Errorf("%w: %v at %s", ErrChunkTooLong, w.cfg.ChunkDuration, f)
	}

	w.format, w.perChunk = f, frames
	return nil
}

// start creates the next chunk under its temporary name with a placeholder header.
func (w *Writer) start() error {
	name := fmt.Sprintf("chunk-%06d.wav", w.next)
	w.next++

	f, err := w.root.OpenFile(name+partialSuffix, os.O_WRONLY|os.O_CREATE|os.O_EXCL, filePerm)
	if err != nil {
		return fmt.Errorf("wavchunk: %s: %w", opCreate, err)
	}
	w.cur, w.curName, w.curFrames = f, name, 0
	w.buf = bufio.NewWriterSize(f, bufferSize)

	if _, err := w.buf.Write(encodeHeader(w.format, 0, false)); err != nil {
		return fmt.Errorf("wavchunk: %s: %w", opWrite, err)
	}
	return nil
}

// finish patches the final header in, fsyncs, closes and renames the current chunk. Without a current chunk it
// does nothing.
func (w *Writer) finish() error {
	if w.cur == nil {
		return nil
	}
	f, buf, name, frames := w.cur, w.buf, w.curName, w.curFrames
	w.cur, w.buf = nil, nil

	err := buf.Flush()
	if err == nil {
		_, err = f.WriteAt(encodeHeader(w.format, uint32(frames), true), 0) //nolint:gosec // frames <= perChunk, bounded in setFormat
	}
	if err == nil {
		err = f.Sync()
	}
	if cerr := f.Close(); err == nil {
		err = cerr
	}
	if err != nil {
		return w.fail(fmt.Errorf("wavchunk: %s %s: %w", opFinalize, name, err))
	}

	// Windows cannot fsync a directory; the rename itself is atomic on NTFS.
	if err := w.root.Rename(name+partialSuffix, name); err != nil {
		return w.fail(fmt.Errorf("wavchunk: %s %s: %w", opRename, name, err))
	}

	if w.cfg.OnChunk != nil {
		w.cfg.OnChunk(Chunk{Name: name, Format: w.format, Frames: frames})
	}
	return nil
}

// abandon simulates a kill in tests: buffered bytes reach the file, but the header stays a placeholder and the
// file keeps its temporary name.
func (w *Writer) abandon() {
	if w.cur != nil {
		_ = w.buf.Flush()
		_ = w.cur.Close()
		w.cur = nil
	}
	w.closed = true
	_ = w.root.Close()
}

// lastNumber returns the highest chunk number in the directory, 0 if there is none.
func lastNumber(root *os.Root) (int, error) {
	names, err := chunkNames(root)
	if err != nil {
		return 0, err
	}
	last := 0
	for _, n := range names {
		m := chunkName.FindStringSubmatch(n)
		if v, err := strconv.Atoi(m[1]); err == nil && v > last {
			last = v
		}
	}
	return last, nil
}

// chunkNames lists the final and temporary chunk files of the directory, sorted.
func chunkNames(root *os.Root) ([]string, error) {
	d, err := root.Open(".")
	if err != nil {
		return nil, fmt.Errorf("wavchunk: %s: %w", opScan, err)
	}
	defer func() { _ = d.Close() }()

	entries, err := d.ReadDir(-1)
	if err != nil {
		return nil, fmt.Errorf("wavchunk: %s: %w", opScan, err)
	}

	var names []string
	for _, e := range entries {
		if e.Type()&fs.ModeType == 0 && chunkName.MatchString(e.Name()) {
			names = append(names, e.Name())
		}
	}
	sort.Strings(names)
	return names, nil
}
